#!/usr/bin/env python3
"""Bundle the native importer and the canonical title registry into the host."""
from pathlib import Path
import json
import sys
sys.path.insert(0, 'scripts')
from titles import TITLES

script = Path('tools/import-linux.py').read_text()
script = script.replace("sys.path.insert(0, str(Path(__file__).resolve().parents[1] / 'scripts'))\nfrom titles import TITLES",
                        'TITLES = ' + repr(TITLES))
Path('generated/import_linux_data.c').write_text(
    '/* Generated by tools/embed-import.py. */\nconst char vct_import_linux[] =\n' +
    '\n'.join(json.dumps(line + '\n') for line in script.splitlines()) + ';\n')
